// @ts-strict-ignore
import styles from "./checkbox-buttons.module.less";
import CheckboxLabel from "./checkbox-label/checkbox-label";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { RefObject, useRef } from "react";
import { FormField, assignToRefs } from "@/core/helpers/form-builder";

/** Single checkbox option rendered by CheckboxButtons */
type CheckboxButtonOption = {
  /** Submitted value for the checkbox option */
  value: string;
  /** Visible label text for the checkbox option */
  label: string;
  /** Optional descriptive text shown below the label */
  description?: string;
};

/** Props for CheckboxButtons */
type CheckboxButtonProps = {
  /** List of checkbox options to render */
  options: CheckboxButtonOption[];
  /** Shared name for the checkbox inputs */
  name?: string;
  /** Selected checkbox values as a comma-separated string; `options[].value` is for a single option */
  value?: string;
  /** Optional legend shown above the checkbox group */
  legend?: string;
  /** Extra class name for the legend element */
  legendClassName?: string;
  /** Extra class name for the outer wrapper */
  wrapperClassName?: string;
  /** Extra class name for each checkbox item wrapper */
  checkboxClassName?: string;
  /**
   * Extra class name applied only to the option description text.
   * This is a styling hook and does not affect checkbox behavior.
   */
  descriptionClassName?: string;
  /**
   * Disables all checkboxes when true.
   * This changes behavior (non-interactive inputs), not visual description styling.
   * Important: use this only during temporary actions (for example while submitting).
   * Do not use disabled state to indicate missing or invalid input; use form validation or banners instead.
   */
  isDisabled?: boolean;
  /**
   * Visual style variant for the checkbox label.
   * Unlike `isDisabled`, this only affects presentation (size/look) and keeps the checkbox interactive.
   */
  variant?: "default" | "small";
  /** Form field config object used as an alternative source for input values/settings */
  formField?: FormField;
  /** Optional ref to the first checkbox input */
  inputRef?: RefObject<HTMLInputElement>;
  /** Callback triggered when selection changes */
  onChange?: (name: string, value: string) => void;
  /** Callback triggered when a specific checkbox option is clicked */
  onOptionClick?: (value: string) => void;
};

/**
 * Displays a group of checkboxes where the user can select one or more options.
 * The component can be used with regular props or with `formField` to get values and settings from a form.
 * When the selection changes, the selected values are returned as a comma-separated string.
 */
const CheckboxButtons = ({
  options,
  name,
  value,
  legend,
  legendClassName = "",
  wrapperClassName,
  checkboxClassName,
  descriptionClassName,
  isDisabled,
  variant = "default",
  formField,
  inputRef,
  onChange,
  onOptionClick,
}: CheckboxButtonProps) => {
  // Extract values from formField if provided
  if (formField) {
    options = options ?? formField.checkBoxOptions ?? [];
    name = name ?? formField.name;
    value = value ?? formField.value;
    isDisabled = isDisabled ?? !formField.isEditable;
  }

  // Use ref for the first checkbox (primary focus target)
  const firstCheckboxRef = useRef<HTMLInputElement>(null);
  const onChangeHandler = (targetValue: string) => {
    if (onOptionClick && typeof onOptionClick === "function") {
      onOptionClick(targetValue);
    }

    if (onChange && typeof onChange === "function") {
      const valuesArray = value ? value.split(", ") : [];
      if (valuesArray.includes(targetValue)) {
        const filteredValues = valuesArray.filter((value) => value !== targetValue);
        onChange(name, filteredValues.join(", "));
      } else {
        valuesArray.push(targetValue);
        onChange(name, valuesArray.join(", "));
      }
    }
  };

  return (
    <div key={name} className={multipleClassNames(styles.outerWrapper, wrapperClassName)}>
      <fieldset className={styles.fieldset}>
        {legend && <legend className={multipleClassNames("bold", legendClassName)}>{legend}</legend>}
        <div className={styles.innerWrapper}>
          {options.map((option, index) => {
            const valuesArray = value ? value.split(", ") : [];
            const checkedValue = valuesArray.includes(option.value);
            const isFirstCheckbox = index === 0;

            return (
              <div key={option.label + index} className={multipleClassNames(styles.itemWrapper, checkboxClassName)}>
                <input
                  className={styles.input}
                  type="checkbox"
                  id={`${option.value}-${index}`}
                  name={name}
                  value={option.value}
                  onChange={(e) => onChangeHandler(e.target.value)}
                  checked={checkedValue}
                  disabled={isDisabled}
                  tabIndex={0}
                  data-is-invalid={isFirstCheckbox && formField?.isValid === false}
                  ref={
                    isFirstCheckbox
                      ? (el) => {
                          assignToRefs(el, firstCheckboxRef, inputRef, formField?.inputRef);
                        }
                      : undefined
                  }
                />
                <label className={styles.label} htmlFor={`${option.value}-${index}`}>
                  <CheckboxLabel
                    variant={variant}
                    labelText={option.label}
                    description={option.description}
                    descriptionClassName={descriptionClassName}
                    isChecked={checkedValue}
                  />
                </label>
              </div>
            );
          })}
        </div>
      </fieldset>
    </div>
  );
};

export default CheckboxButtons;
