import styles from "./checkbox-label.module.less";
import { AnimatePresence, motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers/string-helper";

type Props = {
  labelText: string;
  description?: string;
  descriptionClassName?: string;
  isChecked: boolean;
  variant: "default" | "small";
};

const CheckboxLabel = ({ labelText, description, descriptionClassName, isChecked, variant }: Props) => {
  return (
    <div className={styles.labelWrapper} data-variant={variant} data-has-description={!!description}>
      <div className={multipleClassNames(styles.checkbox, isChecked && styles.checked)}>
        <svg viewBox="4 3 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
          <AnimatePresence>
            {isChecked && (
              <motion.path
                className={`${styles.checkPath}`}
                key="checkboxCheckPath"
                initial={{ pathLength: 0, pathOffset: 0, opacity: 0 }}
                animate={{
                  pathLength: 1,
                  pathOffset: 0,
                  opacity: 1,
                  transition: {
                    delay: 0.1,
                    ease: "easeInOut",
                    pathLength: { duration: 0.175 },
                    opacity: { duration: 0.05 },
                  },
                }}
                exit={{
                  pathLength: 1,
                  pathOffset: 1,
                  transition: {
                    delay: 0.1,
                    ease: "easeInOut",
                    pathLength: { duration: 0.175 },
                  },
                }}
                d="M7 11.7692L10.1579 15L17 8"
                strokeWidth="3"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            )}
          </AnimatePresence>
        </svg>
      </div>
      <p className={styles.labelText}>{labelText}</p>
      {description && <p className={multipleClassNames(styles.description, descriptionClassName)}>{description}</p>}
    </div>
  );
};

export default CheckboxLabel;
